const f = $('Formulário').first();
const pdf = Object.values(f.binary || {}).find(b => /\.pdf$/i.test(b.fileName || ''));
const sessao = 'lmr-sonda2-' + $execution.id;
return [{ json: { sessionId: sessao + '-a', chatInput: 'SONDA 2 (A). Anexei o arquivo ' + (pdf ? pdf.fileName : '?') + '. Abra o arquivo e leia o conteúdo antes de responder. Se precisar carregar o conteúdo completo, carregue. Responda em JSON no fim: {"paginas":<n>,"palavras_pagina_1":"<as 30 primeiras palavras da página 1>","codigos_pagina_1":["até 15 códigos como GP101, QM104G, BS141T que estão na página 1"],"ve_desenho":<true|false>,"como_leu":"<texto, imagem, ferramenta de busca…>"}' }, binary: pdf ? { data: pdf } : {} }];

const a = $('Prepara A').first().json;
const pags = $('Lê PDF').first().json.text;
const p1 = String(Array.isArray(pags) ? pags[0] : pags || '').slice(0, 6000);
return [{ json: { sessionId: a.sessionId.replace(/-a$/, '-c'), chatInput: 'SONDA 2 (C). Sem anexo: abaixo está o texto da página 1, extraído do PDF. Responda em JSON no fim: {"paginas":<n>,"palavras_pagina_1":"<as 30 primeiras palavras da página 1>","codigos_pagina_1":["até 15 códigos como GP101, QM104G, BS141T que estão na página 1"],"ve_desenho":<true|false>,"como_leu":"<texto, imagem, ferramenta de busca…>"}\n\nTEXTO DA PÁGINA 1:\n' + p1 } }];

const corta = v => { const s = typeof v === 'string' ? v : JSON.stringify(v); return s && s.length > 2500 ? s.slice(0, 2500) + '…' : s; };
const de = no => { try { return $(no).first().json; } catch (e) { return { erro: 'não rodou' }; } };
const r = ['AMP Agent A', 'AMP Agent B', 'AMP Agent C'].map(n => { const j = de(n); return n + ' (' + Object.keys(j).join(', ') + ')
  output = ' + corta(j.output != null ? j.output : j.error || j.erro) + '
  files = ' + corta(j.files); });
return [{ json: { relatorio: r.join('

') } }];
